function validate([num, change]) {
  if (num.length < 1 || num.length > 100000) return 'num needs 1 to 10^5 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain only the digits 0-9.';
  if (change.length !== 10) return 'change must have exactly 10 entries.';
  if (change.some(d => d < 0 || d > 9)) return 'Each change[d] is a digit from 0 to 9.';
  return null;
}

