function maximumNumber(num, change) {
  const digits = num.split('').map(Number);
  let i = 0;
  while (i < digits.length && change[digits[i]] <= digits[i]) {
    i++;
  }
  while (i < digits.length && change[digits[i]] >= digits[i]) {
    digits[i] = change[digits[i]];
    i++;
  }
  return digits.join('');
}

