function maximumNumber(num, change) {
  // Try every substring (and no change at all); equal lengths make string order match numeric order.
  let best = num;
  for (let start = 0; start < num.length; start++) {
    for (let end = start + 1; end <= num.length; end++) {
      let candidate = num.slice(0, start);
      for (let k = start; k < end; k++) candidate += String(change[Number(num[k])]);
      candidate += num.slice(end);
      if (candidate > best) best = candidate;
    }
  }
  return best;
}

