function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 8000 + pick(2001) : 1 + pick(8);
  // Each digit maps to itself, to a larger digit or to a smaller one.
  const change = [];
  for (let d = 0; d <= 9; d++) {
    const r = rand();
    change.push(r < 0.35 ? d : r < 0.7 ? d + pick(10 - d) : pick(d + 1));
  }
  // Most digits come from a small palette, so long stretches that keep improving can occur.
  const palette = Array.from({ length: 1 + pick(4) }, () => pick(10));
  let num = '';
  for (let i = 0; i < n; i++) num += String(rand() < 0.85 ? palette[pick(palette.length)] : pick(10));
  return [num, change];
}
